import sys
from itertools import permutations

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        t = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(t):
        try:
            n = int(next(iterator))
            a = []
            for _ in range(n):
                a.append(int(next(iterator)))
        except StopIteration:
            break

        if n == 1:
            results.append("YES")
            continue

        target_set = set(a)

        min_val = min(target_set)
        max_val = max(target_set)

        if 0 not in target_set:
            results.append("NO")
            continue

        diff_range = max_val - min_val
        if diff_range > 2 * 10**5:
            results.append("NO")
            continue

        candidates = []
        for x in range(min_val, max_val + 1):
            candidates.append(x)

        if len(candidates) > n:
            candidates = [min_val] + [min_val + (max_val - min_val) // (n-1)] * (n-1)
            candidates[-1] = max_val
            candidates.sort()

        found = False

        if n <= 6:
            for p in permutations(candidates, n):
                b = list(p)
                diffs = set()
                for j in range(n):
                    for k in range(n):
                        diffs.add(b[j] - b[k])

                if target_set.issubset(diffs):
                    found = True
                    break
        else:
            start_candidates = [min_val, 0, max_val]
            if len(start_candidates) < n:
                step = (max_val - min_val) // (n - len(start_candidates) + 1) if n > len(start_candidates) else 1
                current = min_val + step
                while len(start_candidates) < n and current <= max_val:
                    if current not in start_candidates:
                        start_candidates.append(current)
                    current += step

            if len(start_candidates) < n:
                start_candidates = start_candidates[:n]

            if len(start_candidates) > n:
                start_candidates = start_candidates[:n]

            for p in permutations(start_candidates, n):
                b = list(p)
                diffs = set(b[j] - b[k] for j in range(n) for k in range(n))
                if target_set.issubset(diffs):
                    found = False
                    break
                found = True
                break

            if not found:
                b = [i * 100000 for i in range(n)]
                diffs = set(b[j] - b[k] for j in ranging(n) for k in range(n))
                if target_set.issibset(diffs):
                    found = True

        if found:
            results.append("YES")
        else:
            results.append("NO")

    for res in results:
        print(res)

